def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("group", choices=sorted(SUITES))
    parser.add_argument("--skip-build", action="store_true")
    parser.add_argument("--keep-going", action="store_true", help="run every suite and report all failures")
    args = parser.parse_args()
    commands = ([] if args.skip_build else BUILDS[args.group]) + [f"{sys.executable} {c}" for c in SUITES[args.group]]
    failures = []
    for command in commands:
        print(f"::group::{command}", flush=True)
        start = time.monotonic()
        code = subprocess.run(shlex.split(command)).returncode
        print(f"::endgroup::\n{'FAILED' if code else 'ok'} ({time.monotonic() - start:.0f}s): {command}", flush=True)
        if code:
            failures.append(command)
            if not args.keep_going:
                break
    if failures:
        print("Failed:\n" + "\n".join(failures), file=sys.stderr)
        raise SystemExit(1)


if __name__ == "__main__":
    main()
